package com.citacloud.app.views; import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.math.BigDecimal; import java.util.*;
@Route(value="reportes",layout=MainLayout.class) @PageTitle("Reportes | CitaCloud") @PermitAll public class ReportesView extends VerticalLayout {public ReportesView(CitaService citas,FacturacionService facturacion,PacienteService pacientes){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();List<Cita> agenda=empresa==null?List.of():citas.listarPorEmpresa(empresa);List<Factura> facturas=empresa==null?List.of():facturacion.listar(empresa);BigDecimal ingresos=facturas.stream().map(Factura::getMontoPagado).reduce(BigDecimal.ZERO,BigDecimal::add);setSizeFull();setPadding(true);add(new H2("Reportes"),new Paragraph("Resumen de la empresa autenticada."),new H3("Citas"),new Span("Total: "+agenda.size()+" · Pendientes: "+agenda.stream().filter(c->"PENDIENTE".equals(c.getEstado())).count()+" · Confirmadas: "+agenda.stream().filter(c->"CONFIRMADA".equals(c.getEstado())).count()),new H3("Pacientes e ingresos"),new Span("Pacientes: "+(empresa==null?0:pacientes.listarPorEmpresa(empresa).size())+" · Ingresos cobrados: "+ingresos),new H3("Facturación"),new Span("Facturas: "+facturas.size()+" · Pendientes: "+facturas.stream().filter(f->f.getSaldo().signum()>0).count()));}}
